// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint _val) public {
        // Ensure _val is within reasonable bounds
        _val = bound(_val, 0, type(uint256).max - 1);

        // Call SetMinSum before Initialized
        c.SetMinSum(_val);

        // Now initialize
        c.Initialized();

        // The MinSum should equal _val (no +1 in correct version)
        assertTrue(c.MinSum() == _val);
    }
}

